// 品詞がちがうだけで同じ語から来た形のまとまり（decide 動・decision 名・decisive 形・decisively 副）。
// 単語カードの裏と辞書ページの「ほかの品詞の形」に、いま見ている語とちがう品詞の語を並べる。
// 候補は scripts/word-form-candidates.mjs がつづりの規則で拾い、1組ずつ読んで行き先を決めた。捨てる組は作らない。
// - 同じ語から来た形は、意味が広がった・ずれた語も参考に並べ、ずれ方を WORD_FORM_NOTES に書く（consider と considerable「かなりの」）。
// - つづりが似ているだけの別の語は、取り違えを確かめる語として spelling-confusables.js に入れる（flow と flower）。
